package com.bank.retry.model;

public class Message {
    private final String id;
    private String currentTopic;
    private int attempts;

    public Message(String id, String currentTopic) {
            this.id = id;
            this.currentTopic = currentTopic
            this.attempts = 0;
    }
    public String getId() { return id; }
    public String getCurrentTopic() { return currentTopic; }
    public void setCurrentTopic(String t) { this.currentTopic = t; }
    public int getAttempts() { return attempts; }
    public void incrementAttempts() { attempts++; }

    @Override public String toString() {
        return "msg=" + id + " topic=" + currentTopic + " attempts=" + attempts;
    }
}
