package com.bank.retry.retry;

import java.util.concurrent.ThreadLocalRandom;

// Exponential backoff with jitter: baseDelay * multiplier^(tier), +/- jitter spread.
public class BackoffCalculator {
    private final long baseDelayMs;
    private final double multiplier;
    private final double jitterFraction; // e.g. 0.5 = +/-50%

    public BackoffCalculator(long baseDelayMs, double multiplier, double jitterFraction) {
        this.baseDelayMs = baseDelayMs;
        this.multiplier = multiplier;
        this.jitterFraction = jitterFraction;
    }

    public long delayForTier(int tier) {
        double raw = baseDelayMs * Math.pow(multiplier, tier);
        double spread = raw * jitterFraction;
        double low = raw - spread, high = raw + spread;
        return (long) ThreadLocalRandom.current().nextDouble(low, high);
    }
}
