package com.bank.retry.retry;

import com.bank.retry.model.FailureType;
import com.bank.retry.model.Message;
import java.util.logging.*;

public class RetryRouter {
    private static final Logger log = Logger.getLogger(RetryRouter.class.getName());

    // Graduating ladder of retry topics, then the DLQ.
    private static final String[] TIERS = {"retry.1s", "retry.5s", "retry.30s"};
    private static final String DLQ = "transfers.DLT";

    private final BackoffCalculator backoff;

    public RetryRouter(BackoffCalculator backoff) { this.backoff = backoff; }

    // Decide where a failed message goes next and the delay to apply.
    public String route(Message msg, FailureType type) {
        if (type == FailureType.PERMANENT) {
            log.severe(msg.getId() + " PERMANENT failure -> straight to " + DLQ);
            return DLQ; // skip the ladder entirely
        }
        int tier = msg.getAttempts(); // 0,1,2 -> retry.1s, retry.5s, retry.30s
        if (tier >= TIERS.length) {
            log.warning(msg.getId() + " exhausted all retry tiers -> " + DLQ);
            return DLQ;
        }
        long delay = backoff.delayForTier(tier);
        String next = TIERS[tier];
        log.info(() -> msg.getId() + " transient failure -> " + next
            + " after ~" + delay + "ms (exp backoff + jitter)");
        msg.incrementAttempts();
        msg.setCurrentTopic(next);
        return next;
    }
}
