package com.bank.retry;

import com.bank.retry.model.FailureType;
import com.bank.retry.model.Message;
import com.bank.retry.retry.BackoffCalculator;
import com.bank.retry.retry.RetryRouter;
import java.util.logging.*;

public class RetryDemo {
    private static final Logger log = Logger.getLogger(RetryDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BackoffCalculator backoff = new BackoffCalculator(1000, 5.0, 0.5); // 1s,5s,25s +/-50%
        RetryRouter router = new RetryRouter(backoff);

        // Transient: credit bureau timeout, graduate through the ladder.
        Message m1 = new Message("TRD-001", "transfers");
        log.info("--- transient failure path ---");
        String dest;
        do {
            dest = router.route(m1, FailureType.TRANSIENT);
        } while (!dest.equals("transfers.DLT"));
        log.info("Final destination for " + m1.getId() + " = " + dest);

        // Permanent: invalid account id, skip the ladder.
        Message m2 = new Message("TRD-777", "transfers");
        log.info("--- permanent failure path ---");
        String dest2 = router.route(m2, FailureType.PERMANENT);
        log.info("Final destination for " + m2.getId() + " = " + dest2);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
